mapper.sql:
WHERE er.CONTROL_RESULT = 'RELEASE'
AND er.ORG_ID = #{param.orgId}

    AND er.BIZ_ORG_ID = #{param.bizOrgId}


    AND er.SUBJECT_CODE LIKE CONCAT('%', #{param.subjectCode}, '%')


    AND er.PERIOD LIKE CONCAT('%', #{param.period}, '%')


    AND er.PERIOD >= #{param.startPeriod}


    AND er.PERIOD <= #{param.endPeriod}


    AND er.SOURCE_SYSTEM LIKE CONCAT('%', #{param.sourceSystem}, '%')


    AND er.SOURCE_DOC_ID LIKE CONCAT('%', #{param.sourceDocId}, '%')



    AND staff.REALNAME LIKE CONCAT('%', #{param.operateUser}, '%')


    AND er.EXECUTE_TIME >= TO_DATE(#{param.startTime}, 'YYYY-MM-DD HH24:MI:SS')


    AND er.EXECUTE_TIME <= TO_DATE(#{param.endTime}, 'YYYY-MM-DD HH24:MI:SS')

WHERE er.CONTROL_RESULT = 'TRANSFER'
AND er.ORG_ID = #{param.orgId}

    AND er.BIZ_ORG_ID = #{param.fromOrgId}


    AND er.SUBJECT_CODE LIKE CONCAT('%', #{param.fromSubjectCode}, '%')


    AND er.PERIOD LIKE CONCAT('%', #{param.period}, '%')


    AND er.PERIOD >= #{param.startPeriod}


    AND er.PERIOD <= #{param.endPeriod}


    AND er.SOURCE_SYSTEM LIKE CONCAT('%', #{param.sourceSystem}, '%')


    AND er.SOURCE_DOC_ID LIKE CONCAT('%', #{param.sourceDocId}, '%')



    AND staff.REALNAME LIKE CONCAT('%', #{param.operateUser}, '%')


    AND er.EXECUTE_TIME >= TO_DATE(#{param.startTime}, 'YYYY-MM-DD HH24:MI:SS')


    AND er.EXECUTE_TIME <= TO_DATE(#{param.endTime}, 'YYYY-MM-DD HH24:MI:SS')
